/**
 * @description Guided setup of Integration Connections and Integration Events (the ihSetupEditor screen): the record with
 * the help of its fields, the pickers (objects, fields of the related object, Apex classes, Named Credentials, inbound
 * user access) and save. Reading a record needs access to it; every picker and save need the Integration Hub Admin
 * permission. Field help and paths: IntegrationHubSetupSchema; pickers: IntegrationHubSetupOptions; reading a record:
 * IntegrationHubSetupRecord; building the record to save: IntegrationHubSetupSave.
 * @group Integration Hub
 */
public with sharing class IntegrationHubSetup {

    /** @description Integration Event object. */
    public static final String EVENT_OBJECT = 'IH_Event__c';
    /** @description Integration Connection object. */
    public static final String CONNECTION_OBJECT = 'IH_Connection__c';

    /**
     * @description One choice of a picker.
     */
    public class Option implements Comparable {
        /** @description The value saved. */
        @AuraEnabled
        public String value;
        /** @description The label shown. */
        @AuraEnabled
        public String label;
        /** @description Extra text shown beside the label (may be null). */
        @AuraEnabled
        public String detail;

        /**
         * @description A choice.
         * @param optionValue the value
         * @param optionLabel the label
         * @param optionDetail extra text, or null
         */
        public Option(String optionValue, String optionLabel, String optionDetail) {
            value = optionValue;
            label = optionLabel;
            detail = optionDetail;
        }

        /**
         * @description Sorts by label.
         * @param other another option
         * @return the sort order
         */
        public Integer compareTo(Object other) {
            String mine = label == null ? '' : label.toLowerCase();
            String theirs = ((Option) other).label == null ? '' : ((Option) other).label.toLowerCase();
            return mine.compareTo(theirs);
        }
    }

    /**
     * @description One field of the related object for Payload Fields: a field of the object, or a field of a parent
     * one lookup up (value Account.Name, parent Account).
     */
    public class FieldOption {
        /** @description The path saved in Payload Fields, e.g. Subject or Account.Name. */
        @AuraEnabled
        public String value;
        /** @description Field label. */
        @AuraEnabled
        public String label;
        /** @description Relationship name of the parent, e.g. Account; null for a field of the object itself. */
        @AuraEnabled
        public String parent;
        /** @description Label of the parent lookup, e.g. Account; null for a field of the object itself. */
        @AuraEnabled
        public String parentLabel;

        /**
         * @description A field of the object itself; parent and parentLabel are set for a parent field.
         * @param path the path
         * @param fieldLabel the field label
         */
        public FieldOption(String path, String fieldLabel) {
            value = path;
            label = fieldLabel;
        }
    }

    /**
     * @description One editable field: label, help, type, choices.
     */
    public class FieldInfo {
        /** @description API name. */
        @AuraEnabled
        public String apiName;
        /** @description Label. */
        @AuraEnabled
        public String label;
        /** @description Help text (may be null). */
        @AuraEnabled
        public String help;
        /** @description Schema.DisplayType name, e.g. STRING, PICKLIST, BOOLEAN, DOUBLE, REFERENCE, TEXTAREA. */
        @AuraEnabled
        public String dataType;
        /** @description True when the record cannot be saved without it. */
        @AuraEnabled
        public Boolean required = false;
        /** @description Maximum length of a text field. */
        @AuraEnabled
        public Integer length;
        /** @description Default for a new record, as text (may be null). */
        @AuraEnabled
        public String defaultValue;
        /** @description Active picklist values. */
        @AuraEnabled
        public List<Option> options = new List<Option>();
    }

    /**
     * @description One event of a connection.
     */
    public class EventRow {
        /** @description Event Id. */
        @AuraEnabled
        public Id id;
        /** @description Event key. */
        @AuraEnabled
        public String eventKey;
        /** @description Outbound or Inbound. */
        @AuraEnabled
        public String direction;
        /** @description Active flag. */
        @AuraEnabled
        public Boolean active;
    }

    /**
     * @description What the editor needs for one record (or a new one).
     */
    public class Setup {
        /** @description IH_Event__c or IH_Connection__c. */
        @AuraEnabled
        public String objectApiName;
        /** @description Record Id; null for a new record. */
        @AuraEnabled
        public Id recordId;
        /** @description True when the user has the Integration Hub Admin permission. */
        @AuraEnabled
        public Boolean isAdmin = false;
        /** @description Editable fields with their help, in step order. */
        @AuraEnabled
        public List<FieldInfo> fields = new List<FieldInfo>();
        /** @description Field values by API name; empty for a new record. */
        @AuraEnabled
        public Map<String, Object> values = new Map<String, Object>();
        /** @description Names of the lookups by field API name (Connection__c, Inbound_User__c). */
        @AuraEnabled
        public Map<String, String> names = new Map<String, String>();
        /** @description Event: Named Credential of its connection. */
        @AuraEnabled
        public String credential;
        /** @description True when the Named Credential (of the connection, or of the event's connection) exists in this org. */
        @AuraEnabled
        public Boolean credentialExists = false;
        /** @description Event: the Related Object (value = API name, label, detail = API name and Id prefix); null when blank or unknown. */
        @AuraEnabled
        public Option relatedObject;
        /** @description Connection: Integration Hub Admin, Integration Hub Read, or null for the Inbound User. */
        @AuraEnabled
        public String userAccess;
        /** @description Connection: number of events on it. */
        @AuraEnabled
        public Integer eventCount = 0;
        /** @description Connection: number of inbound events on it. */
        @AuraEnabled
        public Integer inboundCount = 0;
        /** @description Connection: the first events on it, by key. */
        @AuraEnabled
        public List<EventRow> events = new List<EventRow>();
    }

    /**
     * @description The record values and field help for the editor. Anyone who can see the record may read it; isAdmin
     * tells the screen whether to offer Edit.
     * @param objectApiName IH_Event__c or IH_Connection__c (may be blank when recordId is given)
     * @param recordId the record, or null for a new one
     * @return the setup
     */
    @AuraEnabled
    public static Setup getSetup(String objectApiName, Id recordId) {
        String objectName = IntegrationHubSetupRecord.objectOf(objectApiName, recordId);
        Setup s = new Setup();
        s.objectApiName = objectName;
        s.recordId = recordId;
        s.isAdmin = IntegrationHubPreview.isAdmin();
        s.fields = IntegrationHubSetupSchema.fieldInfos(objectName);
        if (recordId != null) {
            IntegrationHubSetupRecord.requireVisible(objectName, recordId);
            IntegrationHubSetupRecord.fill(s);
        }
        return s;
    }

    /**
     * @description Fields of an object for Payload Fields, and of its parents one lookup up (e.g. Account.Name). Admins only.
     * @param objectApiName the related object, e.g. Case
     * @return the field paths
     */
    @AuraEnabled
    public static List<FieldOption> fieldOptions(String objectApiName) {
        IntegrationHubMonitorController.requireAdmin();
        return IntegrationHubSetupSchema.fieldOptions(objectApiName);
    }

    /**
     * @description Objects a trigger can publish, for Related Object. Admins only.
     * @return the objects by label; empty when the org does not list them (the screen then takes free text)
     */
    @AuraEnabled
    public static List<Option> objectOptions() {
        IntegrationHubMonitorController.requireAdmin();
        return IntegrationHubSetupSchema.objectOptions();
    }

    /**
     * @description Concrete Apex classes implementing an Integration Hub interface, test classes left out. Admins only.
     * @param kind payload (IPayloadBuilder), response (IResponseHandler), inbound (IInboundHandler) or auth
     * (IConnectionAuth)
     * @return the class names
     */
    @AuraEnabled
    public static List<Option> classOptions(String kind) {
        IntegrationHubMonitorController.requireAdmin();
        return IntegrationHubSetupOptions.classOptions(kind);
    }

    /**
     * @description Named Credentials of this org. Admins only.
     * @return value = API name, label = label, detail = URL
     */
    @AuraEnabled
    public static List<Option> namedCredentials() {
        IntegrationHubMonitorController.requireAdmin();
        return IntegrationHubSetupOptions.namedCredentials();
    }

    /**
     * @description Which Integration Hub permission set a user has. Admins only.
     * @param userId the user
     * @return Integration Hub Admin, Integration Hub Read, or null
     */
    @AuraEnabled
    public static String userAccess(Id userId) {
        IntegrationHubMonitorController.requireAdmin();
        return IntegrationHubSetupOptions.userAccess(userId);
    }

    /**
     * @description Saves a connection or an event. Admins only. Only Name and the editable Integration Hub fields are
     * accepted; a new record is always saved inactive.
     * @param objectApiName IH_Event__c or IH_Connection__c
     * @param recordJson the field values as a JSON object; with Id to update
     * @return the record Id
     */
    @AuraEnabled
    public static Id save(String objectApiName, String recordJson) {
        IntegrationHubMonitorController.requireAdmin();
        String objectName = IntegrationHubSetupRecord.objectOf(objectApiName, null);
        Map<String, Object> input = IntegrationHubInbound.parseObject(recordJson);
        if (input == null) {
            throw IntegrationHubPreview.auraError('Nothing to save.');
        }
        SObject rec = IntegrationHubSetupSave.toRecord(objectName, input);
        try {
            if (rec.Id == null) {
                IntegrationHubData.insertAll(new List<SObject>{ rec });
            } else {
                IntegrationHubData.updateAll(new List<SObject>{ rec });
            }
        } catch (DmlException e) {
            throw IntegrationHubPreview.auraError(IntegrationHubSetupSave.dmlMessage(objectName, e));
        }
        return rec.Id;
    }
}
